INSERT INTO "decisiones" VALUES('DEC-0001',1,NULL,'estrategia','Topes aprobados por el Director: 150 USD/mes (meses 1-2), 300 USD/mes desde mes 3, 50 USD por producción','ceo','Mensaje del Director del 18-nov-2026','2026-11-18T00:04:49+00:00');
INSERT INTO "decisiones" VALUES('DEC-0002',1,NULL,'estrategia','Sin dominio web por ahora; foco en YouTube y monetización','ceo','Mensaje del Director del 18-nov-2026','2026-11-18T00:04:49+00:00');
INSERT INTO "decisiones" VALUES('DEC-0003',1,'PAL-2026-001','aprobacion_etapa_3','Aprobada etapa 3: Selección del tema','director','Mensaje literal del Director (enviado dos veces): «APRUEBO PAL-2026-001 3 tema 1». Registro MANUAL por excepción: el hook de aprobación no estaba activo en esta sesión (iniciada antes de conectar el repositorio). Tema aprobado: #1 El Palimpsesto de Arquímedes.','2026-11-18T00:23:10+00:00');
INSERT INTO "decisiones" VALUES('DEC-0004',1,'PAL-2026-001','aprobacion_etapa_6','Aprobada etapa 6: Aprobación de la perspectiva','director','Mensaje literal del Director: «APRUEBO PAL-2026-001 6 enfoque A con bloque B». Registro MANUAL: el hook de aprobación sigue inactivo en esta sesión. Enfoque aprobado: A (biografía del objeto) como columna vertebral + bloque B (separar lo demostrado de lo exagerado); mención de Hipérides (C) en el cierre según la recomendación del CEO.','2026-11-18T00:25:47+00:00');
INSERT INTO "decisiones" VALUES('DEC-0005',1,'PAL-2026-001','operativa','Auditoría de fuentes (etapa 8) aplazada a la próxima sesión, abierta con el repositorio seleccionado','ceo','Pedido del Director para repartir el consumo del plan Pro','2026-11-18T00:28:44+00:00');
INSERT INTO "decisiones" VALUES('DEC-0006',1,NULL,'estrategia','Voces: gratuitas y locales (Piper / Kokoro), sin ElevenLabs por ahora','ceo','Pedido del Director: no pagar suscripción de voces','2026-11-18T00:45:02+00:00');
INSERT INTO "decisiones" VALUES('DEC-0007',1,NULL,'estrategia','Métrica de costo principal: consumo del plan Claude Pro por producción (tokens reales + reparto de la cuota)','ceo','Aclaración del Director','2026-11-18T00:45:02+00:00');
INSERT INTO "decisiones" VALUES('DEC-0008',1,NULL,'operativa','Canal verificado por teléfono; Studio configurado con subida privada por defecto','ceo','Confirmado por el Director','2026-11-18T00:45:02+00:00');
INSERT INTO "decisiones" VALUES('DEC-0009',1,NULL,'estrategia','Voz del narrador de Palimpsesto: Kokoro em_alex (voz 1), velocidad 0.95, licencia Apache-2.0','ceo','Elección del Director: «Prefiero la voz 1»','2026-11-18T00:47:15+00:00');
INSERT INTO "decisiones" VALUES('DEC-0010',1,'PAL-2026-001','operativa','Roles ligeros (ceo, guionista, productor, editor, analista, cfo) convertidos en skills que asume la sesión principal; investigador y auditor siguen como subagentes. Importación del consumo ahora incluye los registros de subagentes.','ceo',NULL,'2026-11-18T01:31:31+00:00');
INSERT INTO "decisiones" VALUES('DEC-0011',1,'PAL-2026-001','operativa','Clave de la API de Gemini guardada como secreto de red del entorno Default (nunca en el repo ni en el chat). El proyecto de Google está en el nivel gratuito, sin cuota para modelos de imagen; sin facturación por decisión del Director (DIR-PAL-2026-001-02)','ceo',NULL,'2026-11-18T19:43:16+00:00');
INSERT INTO "decisiones" VALUES('DEC-0012',1,'PAL-2026-001','operativa','Montaje con un motor propio (scripts/montaje.py, PIL + FFmpeg) en lugar de Remotion para el piloto: sin licencias ni instalación adicional; el vídeo se regenera desde montaje.json y tiempos.json','editor',NULL,'2026-11-18T19:43:17+00:00');
INSERT INTO "decisiones" VALUES('DEC-0013',1,'PAL-2026-001','operativa','Recursos pesados fuera de git (imágenes, audio y render): se regeneran con las URL registradas en ''recurso'', scripts/narrar.py y scripts/montaje.py','ceo',NULL,'2026-11-18T19:43:17+00:00');
INSERT INTO "decisiones" VALUES('DEC-0014',1,NULL,'estrategia','Flujo reducido de 21 a 13 etapas (tabla en docs/cambios_aprobados.md); PAL-2026-001 pasa a la etapa nueva 10','ceo','Mensaje literal del Director (18-nov-2026): «Apruebo las 13 etapas, el título y la subida autónoma». Especificación en docs/cambios_aprobados.md','2026-11-18T20:01:37+00:00');
INSERT INTO "decisiones" VALUES('DEC-0015',1,NULL,'estrategia','Título del vídeo: el Guionista propone, el Editor elige el definitivo con la miniatura, el Director lo aprueba en la puerta 11','ceo','Mensaje literal del Director (18-nov-2026): «Apruebo las 13 etapas, el título y la subida autónoma». Especificación en docs/cambios_aprobados.md','2026-11-18T20:01:37+00:00');
INSERT INTO "decisiones" VALUES('DEC-0016',1,NULL,'estrategia','Subida autónoma a YouTube en privado por el Editor; el Analista recomienda hora; el Editor publica o programa solo tras APRUEBO <ID> 12 registrado (cambia la regla 2)','ceo','Mensaje literal del Director (18-nov-2026): «Apruebo las 13 etapas, el título y la subida autónoma». Especificación en docs/cambios_aprobados.md','2026-11-18T20:01:37+00:00');
INSERT INTO "decisiones" VALUES('DEC-0017',1,'PAL-2026-001','migracion_13_etapas','PAL-2026-001 migrada del flujo de 21 etapas al de 13 (DEC-0014). Etapa actual: 10.','ceo','Aprobado por el Director: «Apruebo las 13 etapas, el título y la subida autónoma».','2026-11-18T20:06:57+00:00');
INSERT INTO "decisiones" VALUES('DEC-0018',1,'PAL-2026-001','operativa','PAL-2026-001 cerró la edición antes de la fusión con los Shorts y la subida privada (DEC-0014/0016): ambos se hacen dentro de la etapa 10, junto con las correcciones de la auditoría, antes de la Ficha 11.','ceo','La etapa 9 se migró cerrada; no se reabre para no perder su historial.','2026-11-18T20:09:57+00:00');
INSERT INTO "decisiones" VALUES('DEC-0019',1,'PAL-2026-001','aprobacion_etapa_11','Aprobada etapa 11: Aprobación del vídeo, Shorts y título final','director','Mensaje literal del Director: «APRUEBO PAL-2026-001 11»','2026-11-18T21:29:28+00:00');
